const r = $json;

// XRE ARSA - SAĞLAM OKUMA SÜRÜMÜ
// Kural: Başlık birebir bulunursa SADECE o kolon kullanılır (hücre boşsa boş kalır, başka kolona kaymaz).
// Başlık hiç yoksa: önce başlık içinde arama, en son kolon sırasına göre yedek okuma.

function normKey(s) {
  return String(s ?? '')
    .replace(/ /g, ' ')
    .replace(/²/g, '2')
    .replace(/[İIı]/g, 'I')
    .toUpperCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^A-Z0-9]+/g, '')
    .trim();
}

function cleanValue(v) {
  return String(v ?? '')
    .replace(/ /g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isBadValue(v) {
  const raw = cleanValue(v);
  const x = normKey(raw);
  return !raw || !x || [
    'ALANBOS', 'BOS', 'BOSALAN', 'BELIRTILMEMIS', 'BELIRLENMEMIS',
    'YOK', 'NULL', 'NAN', 'NA', 'TANIMSIZ', 'VERIYOK', '-', '_'
  ].includes(x);
}

const SYSTEM_KEYS = ['row_number', '__rowNum__', 'Row Number'];

const entries = Object.keys(r)
  .filter(k => !SYSTEM_KEYS.includes(k))
  .map(key => ({ key, nkey: normKey(key), value: cleanValue(r[key]) }))
  .filter(e => e.nkey);

// Kolon sırasına göre yedek okuma. Sheet kolon dizilimi:
// A AD SOYAD, B TELEFON, C ŞEHİR, D İLÇE, E MAHALLE, F ADA NO, G PARSEL NO,
// H M2, I M2 FİYATI, J KAKS EMSAL, K TAPU DURUMU, L TARİH, M İLAN NO, N FİYAT, O BİZİM FİYATIMIZ, P AÇIKLAMA
const orderedValues = Object.keys(r)
  .filter(k => !SYSTEM_KEYS.includes(k))
  .map(k => cleanValue(r[k]));

function byIndex(indexZeroBased) {
  const v = orderedValues[indexZeroBased];
  return isBadValue(v) ? '' : cleanValue(v);
}

function firstValid(list) {
  for (const item of list) {
    if (item && !isBadValue(item.value)) return item.value;
  }
  return '';
}

// exact: birebir başlık adları
// test: başlık birebir yoksa kullanılacak başlık-içi arama (varsayılan: 3+ harfli takma adları içeren başlık)
// index: başlık hiç bulunamazsa kolon sırası
function pick(exact, { test, index } = {}) {
  const ns = exact.map(normKey);
  let cands = entries.filter(e => ns.includes(e.nkey));
  if (!cands.length) {
    const t = test || (k => ns.some(a => a.length >= 3 && k.includes(a)));
    cands = entries.filter(e => t(e.nkey));
  }
  if (cands.length) return firstValid(cands);
  return index != null ? byIndex(index) : '';
}

// Türkçe/İngilizce sayı biçimlerini çöz: 1.250.000 / 1.250.000,50 / ₺1.250.000,00 / 1,250,000.50 / 1321,5
function parseNumber(v) {
  const s = cleanValue(v);
  if (isBadValue(s)) return '';
  const m = s.match(/[0-9][0-9.,\s]*/);
  if (!m) return '';
  let x = m[0].replace(/\s/g, '').replace(/[.,]+$/, '');
  const lastDot = x.lastIndexOf('.');
  const lastComma = x.lastIndexOf(',');
  if (lastDot > -1 && lastComma > -1) {
    const dec = lastDot > lastComma ? '.' : ',';
    const thou = dec === '.' ? ',' : '.';
    x = x.split(thou).join('').replace(dec, '.');
  } else {
    const sep = lastDot > -1 ? '.' : (lastComma > -1 ? ',' : '');
    if (sep) {
      const parts = x.split(sep);
      const isThousands = parts.length > 2 || parts[parts.length - 1].length === 3;
      x = isThousands ? parts.join('') : parts.join('.');
    }
  }
  const n = Number(x);
  return Number.isFinite(n) ? String(n) : '';
}

function extractKaksNumber(v) {
  const s = cleanValue(v);
  if (isBadValue(s)) return '';
  // 0,35 / 0.35 / %35 / emsal 1.50 gibi değerleri yakala.
  const m = s.match(/[0-9]+(?:[.,][0-9]+)?/);
  if (!m) return '';
  return m[0].replace(',', '.');
}

const isPriceKey = k => k.includes('FIYAT') || k.includes('BEDEL') || k.includes('TL');

const adSoyad    = pick(['AD SOYAD', 'ADI SOYADI', 'SATICI AD SOYAD', 'İSİM', 'ISIM', 'AD'], { index: 0 });
const telefonRaw = pick(['TELEFON', 'CEP TELEFONU', 'CEP', 'TEL', 'TE'], { index: 1 });
const il         = pick(['ŞEHİR', 'SEHIR', 'İL', 'IL'], { index: 2 });
const ilce       = pick(['İLÇE', 'ILCE'], { index: 3 });
const mahalle    = pick(['MAHALLE', 'MAHALLESİ', 'MAHALLESI', 'MAH'], { index: 4 });
const adaNo      = pick(['ADA NO', 'ADA', 'ADA NUMARASI'], { index: 5 });
const parselNo   = pick(['PARSEL NO', 'PARSEL', 'PARSEL NUMARASI'], { index: 6 });

const m2Raw = pick(['M2', 'M²', 'METREKARE', 'ARSA M2', 'ARSA M²', 'ARSA ALANI', 'ALAN'], {
  test: k => (k.includes('METREKARE') || k.includes('ARSAALAN') || k.includes('ALANM2') || k.includes('M2ALAN')) && !isPriceKey(k),
  index: 7
});
const m2FiyatRaw = pick([
  'M2 FİYATI', 'M² FİYATI', 'M2 FİYAT', 'M² FİYAT', 'M2 BİRİM FİYATI', 'M² BİRİM FİYATI',
  'METREKARE FİYATI', 'BİRİM FİYAT', 'BIRIM FIYAT'
], {
  test: k => (k.includes('M2') || k.includes('METREKARE') || k.includes('BIRIM')) && isPriceKey(k),
  index: 8
});
const kaksRaw = pick(['KAKS EMSAL', 'KAKS (EMSAL)', 'KAKS/EMSAL', 'KAKS', 'EMSAL', 'İMAR EMSALİ', 'IMAR EMSALI'], {
  test: k => k.includes('KAKS') || k.includes('EMSAL'),
  index: 9
});
const tapu       = pick(['TAPU DURUMU', 'TAPU', 'TAPU TİPİ', 'TAPU TIPI'], { index: 10 });
const ilanTarihi = pick(['TARİH', 'TARIH', 'İLAN TARİHİ', 'ILAN TARIHI'], { index: 11 });
const ilanNo = pick(['İLAN NO', 'ILAN NO', 'İLAN NUMARASI', 'ILAN NUMARASI', 'İLAN ID', 'ILAN ID'], {
  test: k => k.includes('ILAN') && (k.includes('NO') || k.includes('NUMARA') || k.includes('ID')),
  index: 12
});
const fiyatRaw = pick(['FİYAT', 'FİYATI', 'SATIŞ FİYATI', 'SATIS FIYATI', 'İLAN FİYATI', 'ILAN FIYATI'], {
  // M2 FİYATI ve BİZİM FİYATIMIZ kolonlarına kaymasın
  test: k => k.includes('FIYAT') && !k.includes('M2') && !k.includes('BIRIM') && !k.includes('METREKARE') && !k.includes('BIZIM') && !k.includes('XRE'),
  index: 13
});
const bizimFiyatRaw = pick(['BİZİM FİYATIMIZ', 'BIZIM FIYATIMIZ', 'XRE FİYAT', 'XRE FIYAT'], {
  test: k => k.includes('BIZIM') || k.includes('XRE'),
  index: 14
});
const aciklama = pick(['AÇIKLAMA', 'ACIKLAMA', 'DETAY', 'NOT', 'NOTLAR'], { index: 15 });

const m2         = parseNumber(m2Raw);
const m2Fiyat    = parseNumber(m2FiyatRaw);
const kaks       = extractKaksNumber(kaksRaw);
const fiyat      = parseNumber(fiyatRaw);
const bizimFiyat = parseNumber(bizimFiyatRaw);

// Hücrede birden fazla numara varsa ("0532... / 0533...") ilkini al.
let telefon = cleanValue(telefonRaw).split(/[\/,;|]/)[0].replace(/\D/g, '');
if (telefon.startsWith('00')) telefon = telefon.slice(2);
if (telefon.startsWith('0')) telefon = '90' + telefon.slice(1);
if (telefon.length === 10 && telefon.startsWith('5')) telefon = '90' + telefon;
const telefonPlus = telefon.length >= 10 ? ('+' + telefon) : '';

const parts = cleanValue(adSoyad).split(' ').filter(Boolean);
const adi = parts.shift() || 'Bilinmeyen';
const soyadi = parts.join(' ') || 'Satıcı';

const adaParsel = [adaNo, parselNo].filter(Boolean).join(' / ');
let title = [il, ilce, mahalle, adaParsel].filter(Boolean).join(' - ');
if (!title) title = 'Yeni Arsa İlanı';
if (ilanNo) title += ` (İlan No: ${ilanNo})`;
if (adSoyad) title += ` (${adSoyad})`;

const fields = {
  TITLE: title,
  CATEGORY_ID: 24,
  STAGE_ID: 'C24:UC_JF95AG', // SAHİBİNDEN YÜKLENENLER
  ASSIGNED_BY_ID: 23180,
  OPPORTUNITY: fiyat || 0,
  CURRENCY_ID: 'TRY',
  COMMENTS: aciklama
};

if (il)          fields['UF_CRM_1782733952602'] = il;
if (ilce)        fields['UF_CRM_1782717914352'] = ilce;
if (mahalle)     fields['UF_CRM_1782732284645'] = mahalle;
if (adaNo)       fields['UF_CRM_1782801103030'] = adaNo;
if (parselNo)    fields['UF_CRM_1782801112430'] = parselNo;
if (m2)          fields['UF_CRM_1782732332912'] = m2;
if (m2Fiyat)     fields['UF_CRM_1782732356777'] = m2Fiyat;
if (kaks)        fields['UF_CRM_1782732390045'] = kaks;
if (tapu)        fields['UF_CRM_1782732403173'] = tapu;
if (ilanTarihi)  fields['UF_CRM_1782733958945'] = ilanTarihi;
if (bizimFiyat)  fields['UF_CRM_1782732441788'] = bizimFiyat;

fields['SOURCE_DESCRIPTION'] = 'Sahibinden - Bot';

return [{
  json: {
    row_number: r.row_number,
    adi,
    soyadi,
    adSoyad,
    telefonPlus,
    debug_found: {
      m2Raw, m2Clean: m2,
      m2FiyatRaw, m2FiyatClean: m2Fiyat,
      kaksRaw, kaksClean: kaks,
      ilanNo,
      fiyatRaw, fiyatClean: fiyat,
      bizimFiyatRaw, bizimFiyatClean: bizimFiyat
    },
    debug_sheet_headers: Object.keys(r),
    debug_ordered_values: orderedValues,
    body: { fields, params: { REGISTER_SONET_EVENT: 'Y' } }
  }
}];

const dv = $('Arsa Verisi Hazırla').item.json;
const fields = Object.assign({}, dv.body.fields);

// Bu node'a 3 yoldan gelinir; kişi ID'si doğrudan gelen veriden okunur
// (döngüde önceki satırın verisi karışmasın diye başka node'a bakılmaz):
//  - Kişi Var mı? (true)  -> { result: { CONTACT: [id] } }
//  - Kişi Oluştur         -> { result: id }
const res = $json.result;
let contactId = '';
if (res && Array.isArray(res.CONTACT) && res.CONTACT.length) {
  contactId = res.CONTACT[0];
} else if (typeof res === 'number' || /^\d+$/.test(String(res ?? ''))) {
  contactId = res;
}

if (contactId) fields['CONTACT_ID'] = Number(contactId);

return [{ json: {
  row_number: dv.row_number,
  body: { fields, params: { REGISTER_SONET_EVENT: 'Y' } }
} }];
